H("886.d.10.D",4,"Fragile items are shipped with:","padding and 'fragile' labels",["no packing","loose packing","open boxes"],"Fragile handling.")
H("886.d.10.E",3,"A packaging engineer compares corrugated boxes, wooden crates and drums for a new product and checks which meet the load and handling needs. She is:","assessing requirements for various packaging types",["ignoring needs","picking at random","skipping packaging"],"Packaging types.")
H("886.d.10.E",4,"A wooden crate is chosen over a cardboard box when the cargo is:","very heavy or needs rigid protection",["very light","edible","soft"],"Crate choice.")
H("886.d.10.F",3,"A designer checks that a carton shows the product name, a barcode, handling icons and legally required warnings. She is analyzing:","visual design and appearance requirements, including displaying required information",["ignoring labels","skipping barcodes","random decor"],"Label requirements.")
H("886.d.10.F",4,"A 'This Side Up' arrow on a carton tells handlers:","how to keep the package oriented during shipping",["the price","the owner","the color"],"Handling marks.")
